import { axios } from "axios";

export const user = async (data) => {
  try {
    const res = await axios({
      method: "POST",
      url: "http://127.0.0.1:8100/api/vi/user",
      data,
    });
    if (res.data.status === "success") {
      showAlert("success", "Welcome");
      window.setTimeout(() => {
        location.assign("/");
      }, 1500);
    }
  } catch (err) {
    
  }
};
